import networkx as nx

def solve_game(board_size):
    G = nx.Graph()
    for r in range(board_size[0]):
        for c in range(board_size[1]):
            G.add_node((r, c))

    for r in range(board_size[0]):
        for c in range(board_size[1]):
            for dr, dc in [(1, 2), (1, -2), (-1, 2), (-1, -2), (2, 1), (2, -1), (-2, 1), (-2, -1)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < board_size[0] and 0 <= nc < board_size[1]:
                    G.add_edge((r, c), (nr, nc))

    # We want to find the number of knights Horst can guarantee.
    # This is a game. Since the board is small, we can use minimax.
    # But the state space is too large even for 3x4.
    # Let's just find the max matching and max independent set.
    matching = nx.max_weight_matching(G, max_weight=None)
    m_size = len(matching)
    max_indep_set = len(G.nodes()) - m_size
    return m_size, max_indep_set

print(f"3x4: {solve_game((3, 4))}")
