                if 0 <= nr < board_size[0] and 0 <= nc < board_size[1]:
                    G.add_edge((r, c), (nr, nc))

    # Use max_weight_matching without the max_weight keyword.
    # The size of the matching is len(matching) // 2 because it's a dict of {u: v, v: u}.
    matching = nx.max_weight_matching(G)
    m_size = len(matching) // 2
    max_indep_set = len(G.nodes()) - m_size
    return m_size, max_indep_set

